import { IMedicament, IMedicamentCategory, IMedicamentForm } from '../@types/medicaments.types';

interface BackMedicament {
  category: string;
  contraindications: string;
  dosage: string;
  for_use: string;
  form: string;
  form_name: string;
  id: string;
  medical_group: string;
  name: string;
  medicament_id: string;
}

export const mapMedicamentsToFront = (backData: BackMedicament): IMedicament => {
  return {
    id: +backData.id,
    name: backData.name,
    category:
      +backData.medical_group > 0
        ? { id: +backData.medical_group, name: backData.category }
        : undefined,
    form: +backData.form > 0 ? { id: +backData.form, name: backData.form_name } : undefined,
    dosage: backData.dosage,
    usages: backData.for_use,
    contraindications: backData.contraindications,
  };
};

export const mapMedicamentsCategoriesToFront = (backData: {
  id: string;
  name: string;
}): IMedicamentCategory => {
  return {
    id: +backData.id,
    name: backData.name,
  };
};

export const mapMedicamentsFormToFront = (backData: {
  id: string;
  name: string;
}): IMedicamentForm => {
  return {
    id: +backData.id,
    name: backData.name,
  };
};

interface MedicamentAddDTO {
  name: string;
  medical_group: string;
  form: string;
  dosage: string;
  for_use: string;
  contraindications: string;
}

export const mapMedicamentToAddDTO = (frontData: Omit<IMedicament, 'id'>): MedicamentAddDTO => {
  if (!frontData.category?.id) {
    throw new Error('Required frontData.category?.id');
  }

  if (!frontData.form?.id) {
    throw new Error('Required frontData.form?.id');
  }

  return {
    name: frontData.name,
    medical_group: frontData.category.id.toString(),
    form: frontData.form?.id.toString(),
    dosage: frontData.dosage,
    for_use: frontData.usages,
    contraindications: frontData.contraindications,
  };
};

interface MedicamentUpdateDTO extends MedicamentAddDTO {
  id: string;
}

export const mapMedicamentToUpdateDTO = (frontData: IMedicament): MedicamentUpdateDTO => {
  return {
    id: frontData.id.toString(),
    ...mapMedicamentToAddDTO(frontData),
  };
};
